import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.D3GK3dQI.js";const p=JSON.parse('{"title":"ADR-001: Kubernetes Informers Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/001-k8s-informers.md","filePath":"adrs/001-k8s-informers.md"}'),n={name:"adrs/001-k8s-informers.md"};function s(c,e,i,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-001-kubernetes-informers-strategy" tabindex="-1">ADR-001: Kubernetes Informers Strategy <a class="header-anchor" href="#adr-001-kubernetes-informers-strategy" aria-label="Permalink to &quot;ADR-001: Kubernetes Informers Strategy&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-06<br><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The metrics exporter needs an up-to-date representation of <code>Gateway</code>, <code>HTTPRoute</code>, <code>Service</code>, <code>Namespace</code>, and <code>ReferenceGrant</code> resources without issuing uncached API requests on every scrape.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The exporter uses the cache-backed client provided by a controller-runtime manager. Calls made by the mapper are served from informer caches after the manager starts and synchronizes them.</p><p>The mapper reads:</p><ul><li><code>gateway.networking.k8s.io/v1</code>: <code>Gateway</code>, <code>HTTPRoute</code>, and <code>ReferenceGrant</code>.</li><li><code>core/v1</code>: <code>Service</code> and <code>Namespace</code>.</li></ul><p>The current implementation lists HTTPRoutes from the cache for each collection cycle and performs cached object lookups while resolving relationships. It does not implement custom field indexers.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive:</strong> Collection avoids direct API-server reads after cache synchronization.</li><li><strong>Negative:</strong> Collection cost grows with the number of HTTPRoutes and resolved relationships. The cache also increases memory usage.</li></ul><h2 id="traceability" tabindex="-1">Traceability <a class="header-anchor" href="#traceability" aria-label="Permalink to &quot;Traceability&quot;">​</a></h2><p>The manager and cached client are configured in <code>cmd/exporter/main.go</code>; relationship reads are implemented in <code>internal/kubernetes/mapper/mapper.go</code>.</p>',13)])])}const u=r(n,[["render",s]]);export{p as __pageData,u as default};
